import {icon} from './ui-icons.js';
const mobile=matchMedia('(max-width:767px)');
const drawer=document.createElement('dialog');drawer.className='garda-dropdrawer';drawer.id='garda-dropdrawer';drawer.setAttribute('aria-labelledby','dropdrawer-title');document.body.append(drawer);
let activeTrigger,onClose;
function close(){drawer.close();}
function open(trigger,title,items){
 if(drawer.open)drawer.close();activeTrigger=trigger;trigger.setAttribute('aria-expanded','true');
 drawer.replaceChildren();const handle=document.createElement('div');handle.className='drawer-handle';drawer.append(handle);
 const header=document.createElement('div');header.className='dropdrawer-header';const heading=document.createElement('h2');heading.id='dropdrawer-title';heading.textContent=title;
 const dismiss=document.createElement('button');dismiss.type='button';dismiss.className='icon-control';dismiss.setAttribute('aria-label','Close menu');dismiss.innerHTML=icon('close');dismiss.addEventListener('click',close);header.append(heading,dismiss);drawer.append(header);
 const list=document.createElement('div');list.className='dropdrawer-items';items.forEach(item=>{const el=document.createElement(item.href?'a':'button');if(item.href)el.href=item.href;else el.type='button';el.className='dropdrawer-item';el.disabled=!!item.disabled;el.textContent=item.label;if(item.selected){el.setAttribute('aria-current','true');el.insertAdjacentHTML('beforeend',icon('check'));}else if(item.href)el.insertAdjacentHTML('beforeend',icon('right'));el.addEventListener('click',()=>{item.action?.();close();});list.append(el);});drawer.append(list);
 drawer.classList.toggle('is-mobile',mobile.matches);drawer.style.removeProperty('top');drawer.style.removeProperty('left');
 if(!mobile.matches){const r=trigger.getBoundingClientRect();drawer.style.top=`${Math.min(r.bottom+8,innerHeight-360)}px`;drawer.style.left=`${Math.max(12,Math.min(r.right-280,innerWidth-292))}px`;}
 drawer.showModal();drawer.querySelector('.dropdrawer-item[aria-current],.dropdrawer-item')?.focus({preventScroll:true});
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches)drawer.animate(mobile.matches?[{transform:'translateY(28px)',opacity:0},{transform:'translateY(0)',opacity:1}]:[{transform:'translateY(-5px)',opacity:0},{transform:'translateY(0)',opacity:1}],{duration:220,easing:'cubic-bezier(.22,1,.36,1)'});
}
drawer.addEventListener('close',()=>{activeTrigger?.setAttribute('aria-expanded','false');activeTrigger?.focus({preventScroll:true});onClose?.();});drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
drawer.addEventListener('keydown',e=>{const items=[...drawer.querySelectorAll('.dropdrawer-item:not(:disabled)')],index=items.indexOf(document.activeElement);let next;if(e.key==='ArrowDown')next=(index+1)%items.length;if(e.key==='ArrowUp')next=(index-1+items.length)%items.length;if(e.key==='Home')next=0;if(e.key==='End')next=items.length-1;if(next!==undefined){e.preventDefault();items[next]?.focus();}});
mobile.addEventListener('change',()=>{if(drawer.open)close();});
const menu=document.querySelector('.mobile-menu-toggle');menu.classList.add('icon-control');menu.innerHTML=icon('menu');menu.setAttribute('aria-label','Open navigation');menu.setAttribute('aria-haspopup','dialog');menu.setAttribute('aria-controls','garda-dropdrawer');
menu.addEventListener('click',()=>open(menu,'Explore GARDA',[...document.querySelectorAll('#main-navigation a')].map(a=>({label:a.textContent.trim(),href:a.getAttribute('href')}))));
function enhance(select){if(select.dataset.dropdrawer)return;select.dataset.dropdrawer='true';const label=select.getAttribute('aria-label')||select.closest('label')?.childNodes[0]?.textContent.trim()||'Options';const field=document.createElement('span');field.className='choice-field';const value=document.createElement('span');value.className='choice-value';const trigger=document.createElement('button');trigger.type='button';trigger.className='icon-control choice-trigger';trigger.innerHTML=icon('chevron');trigger.setAttribute('aria-label',`Choose ${label.toLowerCase()}`);trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');field.append(value,trigger);select.after(field);select.hidden=true;
 function sync(){value.textContent=select.selectedOptions[0]?.textContent.trim()||'';trigger.disabled=select.disabled;trigger.dataset.tooltip=`Change ${label.toLowerCase()}`;trigger.title=trigger.dataset.tooltip;}
 trigger.addEventListener('click',e=>{e.preventDefault();open(trigger,label,[...select.options].map(option=>({label:option.textContent.trim(),selected:option.selected,disabled:option.disabled,action:()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();}})));});select.addEventListener('change',sync);new MutationObserver(sync).observe(select,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['disabled']});sync();}
document.querySelectorAll('.clock-options select,.robot-controls select,.verification-toolbar select').forEach(enhance);
const controls={'clock-back':['left','Previous cycle'],'clock-next':['right','Next cycle'],'clock-reset':['reset','Reset inference'],'clock-next-group':['group','Next group'],'clock-next-layer':['layer','Next layer']};
for(const [id,[name,label]] of Object.entries(controls)){const button=document.getElementById(id);button.innerHTML=icon(name);button.classList.add('icon-control');button.setAttribute('aria-label',label);button.title=label;button.dataset.tooltip=label;}
for(const [selector,name] of [['.gallery-prev','left'],['.gallery-next','right'],['.proposal-prev','left'],['.proposal-next','right']])document.querySelectorAll(selector).forEach(button=>{button.innerHTML=icon(name);button.classList.add('icon-control');button.title=button.getAttribute('aria-label');});

const play=document.getElementById('clock-play');play.classList.add('icon-control');play.innerHTML=icon(play.getAttribute('aria-pressed')==='true'?'pause':'play');play.setAttribute('aria-label','Play inference');play.title='Play inference';
